-- ============================================================
-- Quiz coverage for databases/dynamodb and databases/cloud-databases
-- (overview, fundamentals, intermediate, advanced -- all four
-- tabs exist and carry substantive live content for both).
-- Phase 4 (Databases academy), batch 5: DynamoDB & Cloud Databases.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- databases/dynamodb/overview ----------
('databases', 'dynamodb', 'overview', 'What determines which partition stores a given DynamoDB item, and why does this matter for schema design?', '["The item''s size in bytes", "The partition key, which is hashed to determine placement -- a low-cardinality partition key concentrates items onto fewer partitions, creating hot partitions that throttle performance regardless of total provisioned or on-demand capacity", "The order items are inserted in", "The sort key, not the partition key"]', 1, 'Partition key design is described as the decision that determines everything else in DynamoDB -- a poor choice creates a bottleneck that raising capacity alone cannot fix.', 'beginner'),
('databases', 'dynamodb', 'overview', 'What is the practical difference between DynamoDB''s on-demand and provisioned capacity modes?', '["They are two names for the exact same billing model", "On-demand charges per actual request with no capacity planning needed, well suited to unpredictable traffic; provisioned requires specifying Read/Write Capacity Units ahead of time, cheaper at steady predictable load but requires capacity planning and can throttle if under-provisioned", "Provisioned mode is always cheaper regardless of traffic pattern", "On-demand mode only works for read operations, not writes"]', 1, 'Choosing between these is a genuine tradeoff based on how predictable the workload''s traffic actually is, not a matter of one being universally better.', 'beginner'),
('databases', 'dynamodb', 'overview', 'What does a DynamoDB sort key enable that a table with only a partition key cannot?', '["Sort keys are required on every DynamoDB table and have no optional use case", "A sort key determines the order of items within a partition and enables range queries (>, <, BETWEEN, begins_with) on that key within a single partition -- without one, items can only be looked up by exact partition key match", "Sort keys allow querying across multiple partitions in a single request", "Sort keys replace the need for a partition key entirely"]', 1, 'The combination of a well-chosen partition key plus a sort key is what enables rich query patterns (like \"all of a user''s orders in a date range\") within a single, efficient partition-scoped query.', 'beginner'),
('databases', 'dynamodb', 'overview', 'Why is `scan` generally something to avoid in production DynamoDB usage, compared to `query`?', '["scan and query are functionally identical operations with different names", "scan reads every item in the table (or a full partition range), which is expensive and slow at scale, while query uses the partition key (and optionally sort key) to read only the specific matching items directly -- scan should generally be reserved for one-off/administrative use, not regular application access patterns", "scan can only be used on tables without a sort key", "query requires a GSI to function, while scan does not"]', 1, 'This distinction is foundational to DynamoDB usage -- a well-designed schema should let every regular application access pattern use query or get_item, with scan reserved for exceptional cases.', 'beginner'),
('databases', 'dynamodb', 'overview', 'What is the practical difference between a Global Secondary Index (GSI) and a Local Secondary Index (LSI)?', '["They are identical features with different names depending on AWS region", "A GSI has an entirely new partition key (plus optional sort key), can be added or removed after table creation, and only supports eventually consistent reads; an LSI shares the base table''s partition key with a different sort key, must be defined at table creation time, and can support strongly consistent reads", "LSIs can be added or removed at any time, while GSIs cannot", "GSIs are limited to 5 per table, while LSIs allow up to 20"]', 1, 'These are genuinely different tools for different situations -- GSI flexibility (addable later) versus LSI''s stronger consistency guarantee but fixed-at-creation constraint is a real tradeoff worth knowing explicitly.', 'intermediate'),

-- ---------- databases/dynamodb/fundamentals ----------
('databases', 'dynamodb', 'fundamentals', 'What does the single-table design pattern (`PK="USER#123", SK="PROFILE"` and `PK="USER#123", SK="ORDER#456"`) actually accomplish?', '["It is required by DynamoDB and cannot be avoided", "It lets a single query (matching PK=USER#123) retrieve a user''s profile and all their orders together in one request, avoiding the multiple round-trips a normalized multi-table relational design would require since DynamoDB has no JOINs", "It automatically normalizes data to avoid duplication", "It only works for tables without a sort key"]', 1, 'This key-overloading pattern is the practical technique that lets DynamoDB serve relationship-like access patterns efficiently despite having no JOIN operation at all.', 'intermediate'),
('databases', 'dynamodb', 'fundamentals', 'Why must ExpressionAttributeNames be used for a field like `status` in an UpdateExpression, e.g. `{''#s'': ''status''}`?', '["It is purely optional syntax with no functional purpose", "status is a reserved word in DynamoDB''s expression syntax, so it cannot be used directly in an UpdateExpression -- ExpressionAttributeNames provides a placeholder (#s) that maps to the actual attribute name, working around the reserved-word conflict", "ExpressionAttributeNames is required for every attribute name regardless of whether it''s reserved", "This mapping is only needed for numeric attribute values, not strings"]', 1, 'This reserved-word placeholder mechanism is a common, genuinely necessary DynamoDB pattern -- forgetting it for a reserved word like status produces a real error, not just a style issue.', 'intermediate'),
('databases', 'dynamodb', 'fundamentals', 'In a Python boto3 call, what happens if the same keyword argument (e.g. ExpressionAttributeValues) is passed twice to the same function call?', '["The second value silently overrides the first with no error", "This is a genuine Python SyntaxError (duplicate keyword argument) -- the code would not even run, regardless of what the intended values were", "Both values are merged into a single dictionary automatically", "This only causes an error in Python 2, not Python 3"]', 1, 'This is a real, basic Python language rule (not DynamoDB-specific) worth knowing -- a duplicated keyword argument is a hard syntax error, not a runtime warning or silent override.', 'intermediate'),
('databases', 'dynamodb', 'fundamentals', 'What does designing "access patterns first" mean in the context of DynamoDB, and why does it matter more here than in relational design?', '["It means writing all your SQL queries in advance before creating any tables", "It means listing every specific query your application needs to serve BEFORE designing the table''s key structure -- this matters more in DynamoDB than relational design because DynamoDB has no JOINs or flexible ad-hoc querying, so a schema not designed around actual access patterns often can''t efficiently serve them at all", "Access-pattern-first design is only relevant for tables using GSIs", "This principle only applies to single-table design, not multi-table DynamoDB schemas"]', 1, 'This is the core mindset shift required for effective DynamoDB modeling -- unlike a relational schema that can often support new ad-hoc queries with acceptable performance, a DynamoDB schema not designed around a specific access pattern often genuinely cannot serve it efficiently.', 'beginner'),
('databases', 'dynamodb', 'fundamentals', 'What is the purpose of `ConditionExpression` in a DynamoDB update, e.g. `#s = :expected`?', '["It filters which items are returned by the query, like a WHERE clause on a SELECT", "It makes the update conditional -- the write only succeeds if the specified condition is true at write time (e.g. the status still equals the expected prior value), which is the mechanism behind optimistic locking and preventing lost updates under concurrent writes", "ConditionExpression only works on DELETE operations, not UPDATE", "It has no functional effect and is purely documentation within the code"]', 1, 'ConditionExpression is what makes optimistic locking and conditional business-rule enforcement (like preventing overselling inventory) possible in DynamoDB -- without it, a write always succeeds regardless of the item''s current state.', 'intermediate'),

-- ---------- databases/dynamodb/intermediate ----------
('databases', 'dynamodb', 'intermediate', 'What real problem does adding a time-bucketed suffix to a partition key (e.g. `f"{device_id}#{date.today().isoformat()}"`) solve for time-series data?', '["It reduces the total storage cost of the table", "Without bucketing, a naturally recurring key like device_id alone could concentrate all of one device''s writes onto a single, ever-more-loaded partition over time -- adding a date suffix spreads that device''s writes across multiple partitions instead, avoiding a hot partition", "It is required syntax for any table containing a TIMESTAMP attribute", "This pattern only matters for tables using on-demand billing"]', 1, 'This is the DynamoDB-specific version of a bucketing pattern seen elsewhere in time-series data modeling (also used in Cassandra) -- splitting what would otherwise be one ever-growing hot key into multiple smaller ones.', 'intermediate'),
('databases', 'dynamodb', 'intermediate', 'What guarantee does `TransactWriteItems` provide across multiple items that a series of separate individual writes does not?', '["TransactWriteItems is simply a faster way to perform the same writes, with no guarantee difference", "TransactWriteItems guarantees that a set of up to 100 write operations (potentially spanning multiple tables) either ALL succeed or ALL fail together -- separate individual writes offer no such atomicity, meaning a failure partway through could leave the data in a partially-applied, inconsistent state", "TransactWriteItems removes the need for ConditionExpressions on individual writes", "This guarantee only applies to writes within a single item, not across items"]', 1, 'This atomicity guarantee is exactly why TransactWriteItems is reached for in scenarios like order placement, where an order record, its line items, and an inventory decrement must all succeed or all be rolled back together.', 'intermediate'),
('databases', 'dynamodb', 'intermediate', 'What event types does a DynamoDB Stream capture, and what is a common real use case for consuming them via Lambda?', '["Streams only capture read (GetItem/Query) operations, not writes", "Streams capture INSERT, MODIFY, and REMOVE events for item-level changes -- common use cases triggered via Lambda include syncing changes to a search index, sending notifications on specific field transitions, audit logging, and cross-region replication (which Global Tables use internally)", "Streams are only usable for deleting old data automatically, similar to TTL", "Streams require a separate paid add-on beyond standard DynamoDB pricing"]', 1, 'Recognizing which event type occurred, and inspecting OldImage vs NewImage to detect specific field-level transitions, is the practical skill behind building real event-driven pipelines on DynamoDB Streams.', 'intermediate'),
('databases', 'dynamodb', 'intermediate', 'Why is it necessary to explicitly enable Streams and configure DAX separately, rather than getting them automatically with a new DynamoDB table?', '["Streams and DAX are both enabled by default and cannot be disabled", "They are optional features solving specific, distinct problems -- Streams for event-driven reaction to changes, DAX for microsecond-latency read caching in front of the table -- adding them unconditionally to every table would add cost and complexity for workloads that don''t actually need either capability", "DAX is required before Streams can be enabled on the same table", "This is a legacy limitation only affecting tables created before 2020"]', 1, 'Both are genuinely useful, purpose-built additions rather than defaults -- reaching for DAX or Streams should be driven by an actual, identified need (a read-latency problem, a real event-reaction requirement), not applied reflexively to every table.', 'intermediate'),
('databases', 'dynamodb', 'intermediate', 'In multi-region Global Tables, what conflict resolution strategy does DynamoDB use by default when the same item is written concurrently in two different regions?', '["The write from whichever region has lower latency to the client always wins", "Last-writer-wins based on timestamp -- DynamoDB automatically resolves the conflict by keeping whichever write has the most recent timestamp, without requiring application-level conflict resolution logic", "DynamoDB rejects both writes and requires manual reconciliation", "The region where the table was originally created always takes priority"]', 1, 'Understanding that Global Tables use automatic last-writer-wins resolution (not application-level merge logic) is important context for reasoning about correctness in genuinely concurrent multi-region write scenarios.', 'advanced'),

-- ---------- databases/dynamodb/advanced ----------
('databases', 'dynamodb', 'advanced', 'What does the ~48-hour TTL deletion window mean in practice, and why might this matter for an application relying on TTL for correctness?', '["Items are guaranteed to be deleted at the exact moment their TTL timestamp is reached", "DynamoDB removes expired items automatically but not instantaneously -- deletion typically occurs within about 48 hours of the expiration timestamp, so an application that queries data and depends on TTL-expired items being immediately absent could still see them for some time after their nominal expiration", "TTL deletion only applies to items smaller than 1KB", "The 48-hour window only applies to Global Tables, not single-region tables"]', 1, 'This is a genuinely practical caveat -- TTL is reliable for eventual cleanup and avoiding unbounded storage growth, but it is not a mechanism for guaranteeing an item is gone by a precise instant.', 'advanced'),
('databases', 'dynamodb', 'advanced', 'Why would a team choose provisioned capacity with auto-scaling over on-demand for a mature, steady-traffic production workload?', '["Provisioned capacity is always functionally identical to on-demand with no real difference", "At steady, predictable traffic volume, provisioned capacity is genuinely cheaper per request than on-demand -- auto-scaling handles reasonable variation within bounds, while on-demand''s convenience (no planning, no throttling risk) comes at a real per-request cost premium best suited to unpredictable or new workloads", "On-demand capacity cannot be used at all once a table exceeds a certain size", "Provisioned capacity removes the possibility of throttling entirely"]', 1, 'This is a genuine cost-vs-convenience tradeoff, not a case of one mode being universally better -- the right choice depends on how well-understood and stable the actual traffic pattern is.', 'advanced'),
('databases', 'dynamodb', 'advanced', 'Why is DAX described as a "write-through" cache, and what does that mean for read-after-write consistency through DAX?', '["Write-through means DAX only accelerates write operations, never reads", "A write-through cache updates the cache at write time (not just on subsequent reads), so a write made through DAX is reflected in the cache immediately -- this matters because a naive read-through-only cache could otherwise serve stale data immediately after a write until the cache entry separately expires or is refreshed", "Write-through caching requires manually invalidating the cache after every write", "DAX''s write-through behavior only applies to Global Tables"]', 1, 'Understanding DAX''s specific caching behavior (write-through, not simple read-through) is relevant to correctly reasoning about consistency guarantees when DAX sits in front of a table.', 'advanced'),
('databases', 'dynamodb', 'advanced', 'Why does DynamoDB limit GSIs to a maximum (commonly cited as 20 per table) and LSIs to a stricter maximum (5 per table)?', '["The limits are arbitrary and have no relationship to how the features work", "Each GSI maintains its own separate, independently-provisioned partition/replication structure (with its own RCU/WCU cost), while LSIs share the base table''s partition structure and storage more tightly -- these structural differences underlie why LSIs face a stricter, harder limit and must be defined upfront at table creation", "GSI and LSI limits are identical; this is a common misconception", "The limits exist purely to control AWS billing complexity, unrelated to the underlying architecture"]', 1, 'The differing limits and creation-time constraints between GSIs and LSIs reflect genuine underlying architectural differences in how each index type is implemented and maintained, not an arbitrary AWS policy choice.', 'advanced'),
('databases', 'dynamodb', 'advanced', 'Why can''t a poorly-chosen partition key be easily fixed later without significant work, unlike many other schema adjustments?', '["Partition keys can always be changed instantly via a simple ALTER TABLE-style command", "The partition key determines the physical distribution of every existing item across DynamoDB''s internal partitions -- changing it effectively requires redistributing and rewriting the entire dataset under a new key scheme, which in practice means a full data migration to a new table, not an in-place schema change", "This limitation only applies to tables larger than 1GB", "Partition keys can be changed for free as part of normal GSI management"]', 1, 'This is exactly why partition key design is emphasized as \"the decision that determines everything else\" and worth getting right at design time -- the cost of getting it wrong is a full migration, not a quick fix.', 'advanced'),

-- ---------- databases/cloud-databases/overview ----------
('databases', 'cloud-databases', 'overview', 'What does "managed" actually mean when comparing a cloud-managed database to a self-managed one?', '["Managed databases are always more expensive with no operational benefit", "A managed database service handles provisioning, patching, backups, and failover on the customer''s behalf -- these are real, ongoing operational responsibilities that a self-managed database instance requires the team to handle itself", "Managed only refers to the initial setup process, not ongoing operations", "Managed databases cannot be customized or configured by the customer at all"]', 1, 'Understanding managed services as removing specific, ongoing operational categories of work (not just being \"easier to set up\") is the actual value proposition worth evaluating.', 'beginner'),
('databases', 'cloud-databases', 'overview', 'What genuinely distinguishes a database offering true multi-region writes (like Spanner or Cosmos DB) from most "multi-region" relational database setups?', '["True multi-region write databases are simply faster versions of single-region databases", "Most \"multi-region\" setups support multi-region reads via replicas while writes still go to one primary region; true multi-region write databases accept writes in any configured region, with the database handling conflict resolution and consistency across regions automatically -- a categorically different, more complex capability", "There is no real difference -- this is purely a marketing distinction", "Multi-region writes only matter for NoSQL databases, never relational ones"]', 1, 'This distinction (multi-region reads vs. genuine multi-region writes) is exactly the kind of categorical difference worth being precise about rather than treating \"multi-region\" as one uniform capability.', 'intermediate'),
('databases', 'cloud-databases', 'overview', 'When would a team choose a managed relational database over a managed NoSQL database for a new project?', '["Relational databases should never be chosen for new projects given NoSQL''s scale advantages", "When the workload needs ACID transactions, joins across a well-understood normalized schema -- relational (RDS/Aurora, Cloud SQL, Azure SQL) is the natural fit; NoSQL is built for massive horizontal scale and single-digit-millisecond latency at huge scale, which most new applications don''t actually need from day one", "The choice should always be based purely on which service costs less per month", "NoSQL databases cannot support any form of transactional consistency"]', 1, 'Most application data genuinely fits the relational model comfortably -- reaching for NoSQL primarily because of its scale reputation, before traffic actually justifies it, is called out as a common, avoidable over-engineering trap.', 'beginner'),
('databases', 'cloud-databases', 'overview', 'What are the typical billing dimensions for a cloud-managed database, beyond just a flat monthly instance fee?', '["Cloud databases only ever charge a single flat monthly rate regardless of usage", "Compute (instance size or capacity units), storage (per GB-month), I/O/requests, and data transfer -- NoSQL services like DynamoDB additionally offer on-demand vs. provisioned pricing models on top of these dimensions", "Billing is based solely on the number of tables/collections created, regardless of size or traffic", "Data transfer costs never apply to managed database services"]', 1, 'Understanding the actual billing dimensions (not just \"instance size\") is necessary for reasoning about cost tradeoffs like Aurora''s separate storage/I/O billing or DynamoDB''s on-demand vs. provisioned choice.', 'beginner'),
('databases', 'cloud-databases', 'overview', 'What are the two major categories of consideration when migrating from a self-managed database to a cloud-managed one?', '["Only the total data volume matters -- everything else is automatic", "Schema compatibility (especially when changing engines, like Oracle/SQL Server to Postgres/MySQL) and choosing an appropriate cutover strategy (big-bang vs. dual-write) -- both are real planning decisions, not just \"copy the data over\"", "Migration only requires selecting a target instance size, with no other planning needed", "Cutover strategy is irrelevant as long as a migration tool like AWS DMS is used"]', 1, 'Framing migration as requiring real planning around compatibility and cutover approach (not just data transfer) sets up the deeper treatment of both topics in later sections.', 'intermediate'),

-- ---------- databases/cloud-databases/fundamentals ----------
('databases', 'cloud-databases', 'fundamentals', 'What specific capability does the `--multi-az` flag provide when provisioning an AWS RDS instance?', '["It creates multiple independent databases across different AWS accounts", "It provisions a synchronously-replicated standby in a separate Availability Zone that automatically takes over if the primary fails, providing automatic failover without the team having to write any failover logic themselves", "It automatically distributes read traffic across multiple regions", "It doubles the instance''s compute and storage capacity"]', 1, 'This flag is a concrete example of what \"managed\" actually buys -- a capability (automatic failover) that would otherwise require real engineering effort to build and maintain on a self-managed instance.', 'beginner'),
('databases', 'cloud-databases', 'fundamentals', 'Why can a Multi-AZ standby NOT be used to offload read traffic from the primary, unlike a Read Replica?', '["Multi-AZ standbys actually can serve reads in every configuration", "A Multi-AZ standby exists purely for failover purposes and is not queryable directly in most setups -- its role is availability, not performance; a Read Replica exists specifically to serve read queries and offload the primary, which is its entire purpose", "Read Replicas cannot be promoted to primary, unlike Multi-AZ standbys", "This limitation only applies to PostgreSQL, not MySQL, on RDS"]', 1, 'Conflating these two mechanisms is called out as a common early mistake -- needing both availability and read scaling requires provisioning both, since neither substitutes for the other''s purpose.', 'beginner'),
('databases', 'cloud-databases', 'fundamentals', 'What does `--backup-retention-period 7` actually enable beyond just "backups happening"?', '["It only stores a single backup file 7 days after creation", "It enables automated daily backups plus point-in-time restore for the last 7 days -- meaning the database can be restored to any specific minute within that window, not just to the most recent nightly backup snapshot", "It limits the database to being queried only 7 times per day", "This setting has no effect unless Multi-AZ is also enabled"]', 1, 'Point-in-time restore (not just periodic snapshots) is the more powerful capability this flag actually provides -- worth understanding precisely rather than assuming it just means \"backups happen daily.\"', 'intermediate'),
('databases', 'cloud-databases', 'fundamentals', 'What is a genuine limitation of automated backups and point-in-time restore that teams should understand from day one?', '["Automated backups have no limitations whatsoever and protect against every possible data-loss scenario", "Automated backups protect against infrastructure failure and data corruption discovered within the retention window -- they do NOT protect against a bad deploy or application bug that corrupts data silently and isn''t discovered until after the retention window has already passed the last good state", "Automated backups only work for relational databases, never NoSQL services", "Point-in-time restore can only recover an entire database, never protect against partial corruption"]', 1, 'This caveat directly informs how retention period should actually be chosen -- based on realistic problem-detection time for the kinds of issues that matter, not just a default value picked without that consideration.', 'intermediate'),
('databases', 'cloud-databases', 'fundamentals', 'Why is on-demand pricing generally the better starting choice for a brand-new application, even though provisioned capacity can be cheaper per request?', '["On-demand pricing is always cheaper in every scenario without exception", "A new application''s traffic pattern is genuinely unknown and unpredictable -- on-demand avoids both the capacity-planning exercise (which would be guesswork at this stage) and the throttling risk of under-provisioning, with provisioned capacity''s cost advantage only becoming worth the added planning overhead once traffic is well-understood and steady", "Provisioned capacity cannot be configured for new applications at all", "This guidance only applies to relational databases, not DynamoDB"]', 1, 'This mirrors the same on-demand-vs-reserved tradeoff pattern seen elsewhere in cloud infrastructure -- start flexible when the workload is unknown, optimize for cost once it''s well-understood.', 'intermediate'),

-- ---------- databases/cloud-databases/intermediate ----------
('databases', 'cloud-databases', 'intermediate', 'What structurally makes Aurora''s failover faster than a traditional RDS Postgres failover?', '["Aurora simply uses faster physical hardware than standard RDS instances", "In Aurora, a new compute instance can attach to the existing, already-replicated distributed storage layer rather than waiting for a traditional replica to catch up from replication lag -- because storage is decoupled from any single compute instance''s lifecycle", "Aurora failover is actually not any faster than traditional RDS failover", "Aurora eliminates the need for any failover process by never experiencing downtime"]', 1, 'This storage-compute separation (not just \"AWS''s faster Postgres\") is the actual architectural reason behind Aurora''s specific failover and read-replica-provisioning advantages.', 'intermediate'),
('databases', 'cloud-databases', 'intermediate', 'Why can Aurora''s per-request I/O billing model end up costing more than expected for certain workloads?', '["Aurora never charges for I/O separately from compute", "Aurora bills storage and I/O separately from compute, which rewards workloads with a stable dataset size but variable query load -- an I/O-heavy workload not budgeted with this pricing model in mind can incur real costs that a traditional \"storage included in instance price\" model wouldn''t have surfaced the same way", "I/O costs only apply to write operations, never reads", "This billing model only applies to Aurora Serverless, not standard Aurora"]', 1, 'Understanding Aurora''s specific billing structure (separate I/O pricing) is necessary for accurately forecasting cost for I/O-heavy workloads, not just assuming it behaves like a standard instance-priced database.', 'advanced'),
('databases', 'cloud-databases', 'intermediate', 'What is the practical risk of choosing a genuinely global, multi-region-write database architecture (like Spanner or Cosmos DB) without a measured need for it?', '["There is no real risk -- more resilient architecture is always strictly better regardless of actual requirements", "It introduces real added cost and a meaningfully more complex consistency model to reason about correctly, for a capability (write latency reduction in every region) the application may not actually need if its real traffic doesn''t justify it -- most applications, even global ones, are well served by a single write region with read replicas", "Multi-region write databases are actually cheaper than single-region alternatives", "This architecture choice has no effect on application complexity, only infrastructure cost"]', 1, 'Reaching for the most \"global-sounding\" architecture without a measured latency requirement driving it is called out as a common over-engineering trap -- the added cost and complexity should be justified by an actual, confirmed need.', 'intermediate'),
('databases', 'cloud-databases', 'intermediate', 'Why is a schema compatibility assessment (like using AWS Schema Conversion Tool) recommended BEFORE committing to a migration timeline, rather than during the migration itself?', '["Schema assessment tools can only run after data migration has already completed", "Proprietary features (Oracle PL/SQL packages, SQL Server-specific functions) that don''t have a direct equivalent in the target engine require manual rewriting, not automatic conversion -- discovering this scope of work early, before a timeline is committed to, avoids the migration running significantly over schedule from an unanticipated compatibility gap", "Bulk data transfer is actually the harder, more time-consuming part of most migrations", "This assessment is only relevant for migrations between two different cloud providers, not within one"]', 1, 'Underestimating schema/behavior compatibility work is called out as one of the most common causes of a database migration running significantly over its original timeline -- surfacing this risk early is a genuine risk-management practice.', 'intermediate'),
('databases', 'cloud-databases', 'intermediate', 'What is the core tradeoff between a big-bang and a dual-write migration cutover strategy?', '["Big-bang is always the objectively better choice regardless of the system''s downtime tolerance", "Big-bang requires accepting real downtime during a maintenance window but is simpler to implement and reason about; dual-write avoids a hard downtime window but requires meaningfully more complex engineering to keep both databases genuinely consistent during the transition, carrying its own data-divergence risk if not implemented carefully", "Dual-write is only usable for NoSQL-to-NoSQL migrations, never relational", "The choice between the two has no bearing on actual system downtime"]', 1, 'This is a genuine tradeoff decided by how much downtime is actually acceptable for the specific system -- not a universal best practice favoring one approach in all cases.', 'intermediate'),

-- ---------- databases/cloud-databases/advanced ----------
('databases', 'cloud-databases', 'advanced', 'Why does a Multi-AZ deployment NOT protect against a full regional outage, even though it protects against a single Availability Zone failure?', '["Multi-AZ deployments actually do protect fully against regional outages", "Multi-AZ replicates across separate Availability Zones within the same region -- if the entire region experiences an outage, all AZs within it (including the standby) are affected simultaneously, so genuine cross-region disaster recovery requires a fundamentally different architecture than Multi-AZ alone provides", "Regional outages are theoretical and have never actually occurred", "Multi-AZ only protects against network issues, not power or infrastructure failures"]', 1, 'Understanding the specific failure domain Multi-AZ protects against (AZ-level, not region-level) is exactly why cross-region DR requires starting from real RTO/RPO requirements rather than assuming Multi-AZ alone is sufficient DR.', 'advanced'),
('databases', 'cloud-databases', 'advanced', 'Given a system whose actual business requirement tolerates 15-30 minutes of downtime during a rare regional failure, why would a cross-region read replica with manual promotion be the more defensible DR choice over a full multi-region-write architecture?', '["The multi-region-write architecture would always be strictly better regardless of cost", "Building a full multi-region-write architecture for a system whose actual RTO/RPO tolerance is already well-served by a cheaper option is over-engineering relative to the real requirement -- the DR architecture''s cost and complexity should match genuinely required RTO/RPO, not exceed it by defaulting to the most resilient option available", "Cross-region read replicas cannot be used for disaster recovery under any circumstances", "Manual promotion is actually faster than automatic multi-region failover"]', 1, 'This is the core DR design principle emphasized throughout -- match architecture cost/complexity to actual, measured requirements rather than defaulting to maximum resilience regardless of whether it''s needed.', 'advanced'),
('databases', 'cloud-databases', 'advanced', 'What is the practical mitigation for vendor lock-in risk when choosing a provider-specific managed database like DynamoDB, short of avoiding managed services entirely?', '["There is no way to mitigate vendor lock-in risk once a provider-specific service is chosen", "Isolating data-access logic behind an application-layer abstraction (a repository pattern, a data-access module) so that a future migration, if ever needed, means rewriting that isolated layer rather than every place in the codebase that touches the database directly", "Vendor lock-in can only be avoided by never using any managed database service", "The only real mitigation is negotiating a multi-year contract with the provider"]', 1, 'This is presented as a deliberate, practical middle ground -- accepting a real capability/portability tradeoff while keeping the actual coupling isolated and limited in scope, rather than avoiding managed services reflexively.', 'advanced'),
('databases', 'cloud-databases', 'advanced', 'Why does NoSQL request-shape optimization (avoiding scans, avoiding over-fetching attributes) matter specifically for cost, in a way that''s different from how inefficient relational queries typically show up?', '["NoSQL databases never charge based on request patterns, only flat monthly fees", "For DynamoDB/Cosmos DB, poorly designed queries directly inflate request-based billing in a way that''s invisible until a cost review -- in relational databases, inefficient queries primarily show up as increased latency rather than as a distinct, separate cost line item", "Relational databases actually have the same request-based billing model as DynamoDB", "This distinction only matters for read operations, never writes"]', 1, 'This cost-visibility difference is a genuinely practical operational insight -- an inefficient NoSQL query pattern can silently inflate a bill in a way a DBA monitoring only latency metrics on a relational system might not notice by comparison.', 'advanced'),
('databases', 'cloud-databases', 'advanced', 'When is pursuing genuine multi-cloud database portability (the same workload''s database layer running across two different cloud providers) actually justified, according to the reasoning in this course?', '["Multi-cloud portability should be the default architecture for every new project regardless of requirements", "It is justified for specific, articulable cases -- regulatory requirements mandating data residency across jurisdictions no single provider covers, or genuine risk mitigation against a full single-provider outage for an extremely critical system -- not simply because \"using multiple clouds\" sounds like a resilience best practice", "Multi-cloud portability is never worth the complexity under any circumstances", "This decision only matters for NoSQL databases, never relational ones"]', 1, 'The distinction between using multiple clouds for different independent workloads (common and unremarkable) versus a genuine multi-cloud requirement for one workload''s database layer (rare and high-cost) is the key nuance -- the latter should be an explicit, early, well-justified decision, not a default.', 'advanced');
